import {modelPaperSection,mountModelPaper} from './model-paper.js';
import {modelMetadata} from './model-paper-data.js';
import {grammarTopics} from './exam-lessons.js';
import {vocabularyThemes} from './exam-vocabulary.js';
import {examQuestions,examSources,examCorrections} from './exam-questions.js';

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sound = text => `<button class="sound" data-speak="${esc(text)}" aria-label="Listen to ${esc(text)}">▷</button>`;
const names = Object.fromEntries([...grammarTopics,...vocabularyThemes].map(t=>[t.id,t.title]));
const sourceNames = {notes:'Notes',vocab:'Vocabulary sheet',workbook:'Practice workbook'};
const storeKey = 'wortreise-semester-v1';
function readState(){try{const state=JSON.parse(localStorage.getItem(storeKey));return {answers:state?.answers&&typeof state.answers==='object'?state.answers:{},read:Array.isArray(state?.read)?state.read:[]};}catch{return {answers:{},read:[]};}}
let state=readState(),root,tab='guide',set='grammar',topic='all',page=0,mode='normal',mixed=[],mixedResults=new Map();
const pageSize=15;
const byId = new Map(examQuestions.map(q=>[q.id,q]));
export function normalizeExamAnswer(text,caseSensitive=false){let value=String(text??'').normalize('NFC').trim().replace(/[.,!?;:]/g,'').replace(/\s+/g,' ');return caseSensitive?value:value.toLocaleLowerCase('de');}
export function gradeExamAnswer(q,values){return values.length===q.answers.length&&q.answers.every((choices,i)=>choices.some(choice=>normalizeExamAnswer(choice,q.caseSensitive)===normalizeExamAnswer(values[i],q.caseSensitive)));}
function persist(){try{localStorage.setItem(storeKey,JSON.stringify(state));}catch{message('Progress could not be stored on this browser. You can still practise.');}}
function message(text){const output=root?.querySelector('#exam-message');if(output)output.textContent=text;}
function sourceRef(q){return `${sourceNames[q.source]} · ${q.set==='grammar'?'Grammar':q.set==='vocab'?'Vocabulary':q.block} #${q.num} · p. ${q.page}`;}
function example([de,en,note]){return `<div class="exam-example"><div>${sound(de)}<strong lang="de">${esc(de)}</strong></div><p lang="en">${esc(en)}</p>${note?`<small>${esc(note)}</small>`:''}</div>`;}
function table(data){return `<div class="exam-table-wrap" role="region" aria-label="${esc(data.caption)}" tabindex="0"><table><caption>${esc(data.caption)}</caption><thead><tr>${data.head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.rows.map(row=>`<tr>${row.map((cell,i)=>i?`<td>${esc(cell)}</td>`:`<th scope="row">${esc(cell)}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function guide(){return `<div class="exam-view-head"><div><h2>Understand the rules. Then practise.</h2><p>Follow the workbook’s 14 grammar topics. Each guide has English explanations, German examples and the exact question range to revise.</p></div><span class="exam-chip">14 ZIP grammar guides</span></div><div class="paper-guide-link"><strong>Your model paper tests extra skills too.</strong><p>Revise dative possessives, können/wollen, adjective endings and longer writing tasks in <button class="exam-correction-link" data-exam-tab="model">Model paper & answers ↗</button>.</p></div><div class="exam-foundation"><strong>A quick key to the tables</strong><p><b>Nominative</b> usually marks the subject (who/what does it). <b>Accusative</b> often marks a direct object. <b>Dative</b> marks many recipients and follows specific verbs/prepositions. A noun’s article tells you its gender: der, die or das. Plural means more than one.</p></div><div class="exam-guides">${grammarTopics.map((lesson,i)=>`<details class="exam-guide" id="exam-guide-${lesson.id}"><summary><span class="exam-guide-number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(lesson.title)}</strong><small>${esc(lesson.de)} · Workbook #${lesson.range}</small></span><span class="exam-expand" aria-hidden="true">+</span></summary><div class="exam-guide-body"><p class="exam-lead">${esc(lesson.summary)}</p><p class="exam-source">${sourceNames[lesson.source]} · pp. ${esc(lesson.pages)}</p><ol class="exam-steps">${lesson.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>${lesson.tables.map(table).join('')}<h3>Hear it in a sentence</h3><div class="exam-examples">${lesson.examples.map(example).join('')}</div><div class="exam-trap"><strong>Watch for these exam mistakes</strong><ul>${lesson.traps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><div class="exam-guide-end"><label><input type="checkbox" data-exam-read="${lesson.id}" ${state.read.includes(lesson.id)?'checked':''}> I have revised this topic</label><button class="btn small-btn" data-exam-practise="${lesson.id}">Practise #${lesson.range} →</button></div></div></details>`).join('')}</div>`;}
function vocabulary(){return `<div class="exam-view-head"><div><h2>The vocabulary in your German folder.</h2><p>Includes the picture-only clothing, landmark, weather and direction pages. Listen, learn the article, then test the meaning.</p></div><span class="exam-chip">9 source themes</span></div><div class="exam-filters"><label class="field">Theme<select id="exam-vocab-theme">${vocabularyThemes.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}<option value="all">All vocabulary themes</option></select></label><label class="field">Find German or English<input id="exam-vocab-search" type="search" placeholder="Try Werkstatt, rain or clothing…"></label><label class="exam-check"><input id="exam-hide-meanings" type="checkbox"> Hide meanings for recall</label></div><div id="exam-vocab-intro"></div><p id="exam-vocab-count" class="exam-source"></p><div id="exam-vocab-grid" class="exam-vocab-grid"></div>`;}
function practice(){return `<div class="exam-view-head"><div><h2>Your semester practice room.</h2><p>307 questions from the ZIP materials: 210 grammar, 45 vocabulary and 52 notes exercises. Questions keep their original numbering within each source block.</p></div><button class="pill" data-exam-mix>⇄ Mix 20 questions</button></div><div class="exam-filters"><label class="field">Question set<select id="exam-question-set"><option value="grammar">Workbook · 210 grammar questions</option><option value="vocab">Workbook · 45 vocabulary questions</option><option value="notes">Notes · 52 questions</option><option value="all">All ZIP exercises</option></select></label><label class="field">Topic<select id="exam-question-topic"></select></label><button class="pill" data-exam-mistakes>Review mistakes</button></div><div class="exam-practice-note">Enter each missing word in its own box. Keep ä, ö, ü and ß. Formal <b>Sie / Ihnen</b> are case-sensitive. Ending exercises ask for the <b>complete missing word</b>. For joined sentences, listed equivalent versions are accepted; other valid phrasing may need comparison with the model.</div><div class="exam-practice-toolbar"><strong id="exam-selection-label"></strong><span id="exam-selection-score" role="status"></span><button class="btn small-btn" data-exam-check-page>Check filled answers</button></div><div id="exam-questions"></div><div class="exam-pagination"><button class="pill" data-exam-page="-1">← Previous</button><span id="exam-page-label"></span><button class="pill" data-exam-page="1">Next →</button></div>`;}
function sources(){return `<div class="exam-view-head"><div><h2>Corrections and source map.</h2><p>These notes clarify mistakes or ambiguous prompts in the supplied PDFs. The practice uses the corrected form and labels affected questions.</p></div><span class="exam-chip">Source checked</span></div><div class="exam-source-list">${[...examSources,{id:'model',name:modelMetadata.fileName,pages:modelMetadata.pages}].map(s=>`<article><span class="exam-file-icon" aria-hidden="true">▤</span><div><h3>${esc(s.name)}</h3><p>${s.pages} pages · ${s.id==='notes'?'welch-, dies-, dative pronouns, man, question words and time':s.id==='vocab'?'nine vocabulary themes, including scanned picture charts':s.id==='model'?'six main questions, 180 minutes, 90 marks; worked answers and writing models in the Model paper tab':'14 grammar topics, 210 grammar questions and 45 vocabulary questions with answer keys'}</p></div></article>`).join('')}</div><div class="exam-correction-grid">${examCorrections.map(c=>`<article class="exam-correction"><div class="exam-source">${sourceNames[c.source]} · p. ${c.page}</div><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p>${c.example?example([c.example,'Corrected model sentence']):''}</article>`).join('')}</div><div class="exam-foundation"><strong>What this section covers</strong><p>The German-folder materials supplied from EndSem.zip, plus your uploaded German term-end model question paper. The model paper specifies 180 minutes and 90 marks. Worked answers are study aids; the model PDF did not include an official answer key.</p></div>`;}
export function examSection(rate=1){return `<div class="exam-hero"><div><span class="exam-badge">YOUR GERMAN FOLDER + MODEL PAPER · SEMESTER REVISION</span><h1>Your semester.<br><em>One focused space.</em></h1><p>Your German notes, vocabulary sheet, practice book and model question paper, organized with explanations and worked answers for revision with your classmates.</p><div class="row"><button class="btn" data-exam-tab="guide">Open the study guide ↗</button><button class="pill" data-exam-share>Copy exam section link</button></div></div><div class="exam-orb" aria-hidden="true"><span>Prüfung</span><strong>DE</strong><small>READ · LISTEN · RECALL</small></div></div><div class="exam-metrics"><div><strong>14</strong><span>Grammar topics</span></div><div><strong>9</strong><span>Vocabulary themes</span></div><div><strong>307</strong><span>ZIP practice questions</span></div><div><strong id="exam-correct-count">0</strong><span>Correct on this device</span></div></div><div class="exam-progress-line"><span id="exam-read-count">0 / 14 topics revised</span><div class="progress"><span id="exam-read-progress"></span></div><small>Your exam progress is separate from the everyday course.</small></div><div class="controls"><label>Playback speed <input class="speed-slider" aria-label="Exam playback speed" type="range" min="0.5" max="1.25" step="0.05" value="${rate}"><output class="speed-output">${rate.toFixed(2)}×</output></label><button class="pill" data-action="stop">Stop audio ◼</button><span class="micro">Use the German voice selector above for spoken examples.</span></div><nav class="exam-tabs" aria-label="Semester revision sections"><button class="pill" data-exam-tab="guide" aria-pressed="true">01 · Study guide</button><button class="pill" data-exam-tab="vocabulary" aria-pressed="false">02 · Vocabulary</button><button class="pill" data-exam-tab="practice" aria-pressed="false">03 · Exam practice</button><button class="pill" data-exam-tab="model" aria-pressed="false">04 · Model paper & answers</button><button class="pill" data-exam-tab="sources" aria-pressed="false">05 · Corrections & sources</button></nav><p id="exam-message" role="status" aria-live="polite"></p><div id="exam-panel-guide">${guide()}</div><div id="exam-panel-vocabulary" hidden>${vocabulary()}</div><div id="exam-panel-practice" hidden>${practice()}</div><div id="exam-panel-model" hidden><div id="exam-model">${modelPaperSection()}</div></div><div id="exam-panel-sources" hidden>${sources()}</div>`;}
function updateStats(){const correct=examQuestions.filter(q=>state.answers[q.id]?.status==='correct').length;root.querySelector('#exam-correct-count').textContent=correct;const read=grammarTopics.filter(t=>state.read.includes(t.id)).length;root.querySelector('#exam-read-count').textContent=`${read} / 14 topics revised`;root.querySelector('#exam-read-progress').style.width=(read/14*100)+'%';}
function showTab(name,scroll=true){tab=name;for(const key of ['guide','vocabulary','practice','model','sources'])root.querySelector('#exam-panel-'+key).hidden=key!==name;root.querySelectorAll('.exam-tabs [data-exam-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.examTab===name)));if(scroll)root.querySelector('.exam-tabs').scrollIntoView({block:'start',behavior:'instant'});message('');}
function renderVocabulary(){const selected=root.querySelector('#exam-vocab-theme').value,q=root.querySelector('#exam-vocab-search').value.trim().toLocaleLowerCase('de'),hide=root.querySelector('#exam-hide-meanings').checked;const themes=vocabularyThemes.filter(t=>selected==='all'||t.id===selected);root.querySelector('#exam-vocab-intro').innerHTML=themes.length===1?`<div class="exam-foundation"><h3>${esc(themes[0].title)}</h3><p>${esc(themes[0].intro)}</p><p class="exam-source">Vocabulary sheet · p. ${themes[0].page}${themes[0].id==='workplaces'?'–11':themes[0].id==='weather'?', 7':themes[0].id==='travel'?'–4':''}</p>${themes[0].examples.map(example).join('')}</div>`:'';const entries=themes.flatMap(t=>t.entries.map(e=>({...e,theme:t.title}))).filter(e=>(e.de+' '+e.en+' '+e.theme).toLocaleLowerCase('de').includes(q));root.querySelector('#exam-vocab-count').textContent=`${entries.length} vocabulary entries · learn the article with the noun`;root.querySelector('#exam-vocab-grid').innerHTML=entries.map(e=>`<article class="exam-word"><div class="exam-word-top">${sound(e.de)}<strong lang="de">${esc(e.de)}</strong></div>${hide?`<details><summary>Show meaning</summary><p>${esc(e.en)}</p></details>`:`<p>${esc(e.en)}</p>`}${e.plural?`<small lang="de">Plural: ${esc(e.plural)}</small>`:''}<span class="exam-source">${esc(e.theme)} · p. ${e.page}</span><button class="exam-spell-link" data-exam-spell="${esc(e.de)}">Spell aloud ↗</button></article>`).join('')||'<p>No matching words in this theme. Try another theme or a shorter search.</p>';}
function topicOptions(){const list=examQuestions.filter(q=>set==='all'||q.set===set),ids=[...new Set(list.map(q=>q.topic))];root.querySelector('#exam-question-topic').innerHTML='<option value="all">All topics in this set</option>'+ids.map(id=>`<option value="${id}">${esc(names[id])}</option>`).join('');if(!ids.includes(topic))topic='all';root.querySelector('#exam-question-topic').value=topic;}
function selectedQuestions(){if(mode==='mix')return mixed;if(mode==='mistakes')return examQuestions.filter(q=>state.answers[q.id]?.status==='incorrect');return examQuestions.filter(q=>(set==='all'||q.set===set)&&(topic==='all'||q.topic===topic));}
function record(q){return mode==='mix'?mixedResults.get(q.id):state.answers[q.id];}
function feedback(q,r){if(!r)return '';if(r.status==='revealed')return `<strong>Model: ${esc(q.answers.map(a=>a[0]).join(' · '))}</strong><p>${esc(q.reason)}</p><small>Revealing does not count as correct. Type the answer and check it yourself.</small>`;return `<strong>${r.status==='correct'?'✓ Correct.':'Not quite. Check the form and try again.'}</strong><p>${esc(q.reason)}</p>`;}
function questionCard(q){const r=record(q);return `<article class="exam-question" data-exam-question="${q.id}"><div class="exam-question-head"><span class="exam-source">${esc(sourceRef(q))}</span>${q.correction?'<button class="exam-correction-link" data-exam-tab="sources">Source clarified ↗</button>':''}</div><h3>${esc(q.prompt)}</h3><div class="exam-answer-fields">${q.answers.map((choices,i)=>`<label> ${q.answers.length>1?'Blank '+(i+1):q.set==='grammar'&&q.num>=196?'Joined sentence':'Your answer'}<input id="exam-${q.id}-${i}" data-exam-input="${q.id}" data-exam-blank="${i}" autocomplete="off" spellcheck="false" lang="de" maxlength="450" value="${esc(r?.values?.[i]||'')}"></label>`).join('')}</div><div class="exam-answer-tools"><button class="btn small-btn" data-exam-check="${q.id}">Check answer</button><button class="pill" data-exam-reveal="${q.id}">Show model answer</button><div class="exam-special-keys">${['ä','ö','ü','ß','Ä','Ö','Ü'].map(c=>`<button aria-label="Insert ${c} into this answer" data-exam-key="${c}" data-exam-for="${q.id}">${c}</button>`).join('')}</div></div><div class="exam-feedback ${r?.status==='incorrect'?'is-error':''}" id="exam-feedback-${q.id}" role="status">${feedback(q,r)}</div></article>`;}
function updateSelectionScore(){const list=selectedQuestions(),correct=list.filter(q=>record(q)?.status==='correct').length;root.querySelector('#exam-selection-score').textContent=`${correct} / ${list.length} correct${mode==='mix'?' in this mixed revision':''}`;}
function renderQuestions(){const list=selectedQuestions(),last=Math.max(0,Math.ceil(list.length/pageSize)-1);page=Math.max(0,Math.min(page,last));const visible=list.slice(page*pageSize,(page+1)*pageSize);root.querySelector('#exam-selection-label').textContent=mode==='mix'?'Mixed revision · 20 source questions':mode==='mistakes'?'Your last incorrect answers':`${list.length} questions · ${topic==='all'?'all selected topics':names[topic]}`;root.querySelector('#exam-questions').innerHTML=visible.map(questionCard).join('')||'<div class="exam-foundation"><strong>No questions here yet.</strong><p>Choose a question set, or complete some practice before reviewing mistakes.</p></div>';root.querySelector('#exam-page-label').textContent=list.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,list.length)} of ${list.length}`:'0 questions';root.querySelector('[data-exam-page="-1"]').disabled=page===0;root.querySelector('[data-exam-page="1"]').disabled=page===last;updateSelectionScore();}
function values(q){return q.answers.map((_,i)=>root.querySelector(`#exam-${q.id}-${i}`)?.value||'');}
function saveRecord(q,r){state.answers[q.id]=r;if(mode==='mix')mixedResults.set(q.id,r);persist();updateStats();updateSelectionScore();}
function check(q){const input=values(q),output=root.querySelector('#exam-feedback-'+q.id);if(input.some(v=>!v.trim())){output.classList.add('is-error');output.textContent='Fill every answer box for this question first.';return false;}const correct=gradeExamAnswer(q,input),r={status:correct?'correct':'incorrect',values:input};saveRecord(q,r);output.classList.toggle('is-error',!correct);output.innerHTML=feedback(q,r);return true;}
function shuffle(items){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
export function mountExam(){root=document.querySelector('#exam');if(!root)return;updateStats();renderVocabulary();topicOptions();renderQuestions();mountModelPaper();let activeAnswer=null;
 root.addEventListener('focusin',e=>{if(e.target.matches('[data-exam-input]'))activeAnswer=e.target;});
 root.addEventListener('input',e=>{if(e.target.id==='exam-vocab-search')renderVocabulary();});
 root.addEventListener('change',e=>{if(e.target.dataset.examRead){state.read=e.target.checked?[...new Set([...state.read,e.target.dataset.examRead])]:state.read.filter(x=>x!==e.target.dataset.examRead);persist();updateStats();}if(['exam-vocab-theme','exam-hide-meanings'].includes(e.target.id))renderVocabulary();if(e.target.id==='exam-question-set'){set=e.target.value;topic='all';page=0;mode='normal';topicOptions();renderQuestions();}if(e.target.id==='exam-question-topic'){topic=e.target.value;page=0;mode='normal';renderQuestions();}});
 root.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-exam-input]')){e.preventDefault();check(byId.get(e.target.dataset.examInput));}});
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const data=b.dataset;
 if(data.examTab){showTab(data.examTab);return;}
 if(data.examShare!==undefined){const url=new URL(location.href);url.hash='exam';try{await navigator.clipboard.writeText(url.href);message('Exam section link copied. Share it with your classmates.');}catch{message('Share this exam link: '+url.href);}return;}
 if(data.examPractise){set='grammar';topic=data.examPractise;mode='normal';page=0;root.querySelector('#exam-question-set').value=set;topicOptions();renderQuestions();showTab('practice');return;}
 if(data.examSpell){document.querySelector('#speak-text').value=data.examSpell;location.hash='sounds';return;}
 if(data.examCheck){check(byId.get(data.examCheck));return;}
 if(data.examReveal){const q=byId.get(data.examReveal),r={status:'revealed',values:values(q)};saveRecord(q,r);const output=root.querySelector('#exam-feedback-'+q.id);output.classList.remove('is-error');output.innerHTML=feedback(q,r);return;}
 if(data.examKey){const card=b.closest('[data-exam-question]');const input=activeAnswer&&card.contains(activeAnswer)?activeAnswer:card.querySelector('input');const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(data.examKey,start,end,'end');input.focus();return;}
 if(data.examPage){page+=Number(data.examPage);renderQuestions();root.querySelector('.exam-practice-toolbar').scrollIntoView({block:'start',behavior:'instant'});return;}
 if(data.examCheckPage!==undefined){let count=0;root.querySelectorAll('[data-exam-question]').forEach(card=>{const q=byId.get(card.dataset.examQuestion);if(values(q).some(v=>v.trim())&&check(q))count++;});message(count?`Checked ${count} filled question${count===1?'':'s'}. Review the feedback below.`:'Enter your answers first, then check them.');return;}
 if(data.examMix!==undefined){mixed=shuffle([...grammarTopics.map(t=>shuffle(examQuestions.filter(q=>q.set==='grammar'&&q.topic===t.id))[0]),...shuffle(examQuestions.filter(q=>q.set==='vocab')).slice(0,6)]);mixedResults.clear();mode='mix';page=0;renderQuestions();showTab('practice');return;}
 if(data.examMistakes!==undefined){mode='mistakes';page=0;renderQuestions();message('Showing the last answers marked incorrect. A new correct attempt clears that question from your next review.');return;}
 });
}

export function openExamHash(hash){if(hash==='exam-model'&&root){showTab('model',false);return true;}return false;}
